vocabulary:[V('companion','/kəmˈpæniən/','伙伴','a travelling companion','旅伴'),V('acquaintance','/əˈkweɪntəns/','熟人','a casual acquaintance','点头之交'),V('trust','/trʌst/','信任','build mutual trust','建立相互信任'),V('loyalty','/ˈlɔɪəlti/','忠诚','show loyalty to a friend','对朋友忠诚'),V('honesty','/ˈɒnəsti/','诚实','value honesty','重视诚实'),V('reliable','/rɪˈlaɪəbl/','可靠的','a reliable friend','可靠的朋友'),V('sociable','/ˈsəʊʃəbl/','善于交际的','a sociable person','善于交际的人'),V('introverted','/ˈɪntrəvɜːtɪd/','内向的','an introverted child','内向的孩子'),V('confide','/kənˈfaɪd/','倾诉','confide in a close friend','向密友倾诉'),V('encourage','/ɪnˈkʌrɪdʒ/','鼓励','encourage one another','互相鼓励'),V('reassure','/ˌriːəˈʃʊə/','使安心','reassure a worried friend','安慰担忧的朋友'),V('misunderstanding','/ˌmɪsʌndəˈstændɪŋ/','误会','sort out a misunderstanding','解决误会'),V('companionship','/kəmˈpæniənʃɪp/','陪伴','provide companionship','提供陪伴'),V('shared interest','/ʃeəd ˈɪntrəst/','共同兴趣','bond over a shared interest','因共同兴趣建立联系'),V('social circle','/ˈsəʊʃl ˌsɜːkl/','社交圈','expand a social circle','扩大社交圈'),V('long-distance friendship','/ˌlɒŋ ˈdɪstəns ˈfrendʃɪp/','异地友谊','maintain a long-distance friendship','维持异地友谊'),V('peer pressure','/ˈpɪə preʃə/','同伴压力','resist peer pressure','抵制同伴压力'),V('keep in touch','/kiːp ɪn tʌtʃ/','保持联系','keep in touch online','在网上保持联系'),V('lose touch','/luːz tʌtʃ/','失去联系','gradually lose touch','逐渐失去联系'),V('have something in common','/hæv ˌsʌmθɪŋ ɪn ˈkɒmən/','有共同点','have a lot in common','有许多共同点')],
paraphrases:[{base:'friend',options:['close friend','companion','acquaintance'],note:'acquaintance 只是认识的人，关系通常不亲密。'},{base:'trust someone',options:['rely on someone','have confidence in someone','count on someone'],note:'count on 较口语，强调可以依靠。'},{base:'meet friends',options:['socialise with friends','get together','catch up'],note:'catch up 强调一段时间未见后聊天了解近况。'},{base:'same interests',options:['shared interests','common ground','have a lot in common'],note:'common ground 也可指共同立场。'},{base:'support a friend',options:['be there for a friend','offer reassurance','lend emotional support'],note:'lend support 是较正式搭配。'},{base:'stop being friends',options:['fall out','drift apart','end a friendship'],note:'drift apart 通常是自然疏远，不一定发生争吵。'},{base:'make friends',options:['form friendships','build social connections','strike up a friendship'],note:'strike up 强调开始建立关系。'},{base:'good friendship',options:['close friendship','lasting friendship','supportive friendship'],note:'lasting 强调持续时间长。'}],
sentences:[{pattern:'A friendship is more likely to last when + both people + make an effort to stay in touch.',cn:'当双方都努力保持联系时，友谊更可能长久。',example:'A friendship is more likely to last when both people make an effort to stay in touch.'},{pattern:'What I value most in a friend is + quality or behaviour.',cn:'我最看重朋友的……',example:'What I value most in a friend is the ability to listen without judging.'},{pattern:'Having common interests may help people connect, but + clause.',cn:'共同兴趣可能帮助人们建立联系，但是……',example:'Having common interests may help people connect, but trust is what keeps the friendship strong.'}],
