expressions:[{text:'take up a hobby',cn:'开始一项爱好',example:'I took up photography during a long summer holiday.'},{text:'lose track of time',cn:'忘记时间',example:'I often lose track of time when I’m drawing.'},{text:'do something for fun',cn:'为了乐趣做某事',example:'I play the guitar for fun rather than performing.'},{text:'try my hand at',cn:'尝试做某事',example:'I’d like to try my hand at making pottery.'},{text:'a good way to unwind',cn:'很好的放松方式',example:'Gardening is a good way to unwind after a busy day.'}],
