paraphrases:[{base:'song',options:['track','piece of music','composition'],note:'track 常指录制的单曲；composition 较正式。'},{base:'easy to remember',options:['catchy','memorable','instantly recognisable'],note:'catchy 常用于旋律，通常是积极评价。'},{base:'perform live',options:['give a live performance','play in concert','appear on stage'],note:'play in concert 多用于音乐家。'},{base:'type of music',options:['genre','musical style','category'],note:'genre 是最自然的正式词。'},{base:'like music',options:['enjoy listening to music','be passionate about music','have broad musical tastes'],note:'passionate about 表示兴趣很强。'},{base:'make music',options:['compose','produce a track','create a piece'],note:'compose 侧重作曲；produce 涉及录音制作。'},{base:'practise together',options:['rehearse','have a rehearsal','prepare as an ensemble'],note:'rehearse 可作及物或不及物动词。'},{base:'affect feelings',options:['evoke emotion','influence mood','trigger an emotional response'],note:'evoke emotion 常用于较正式分析。'}],
sentences:[{pattern:'Whenever I hear + piece of music, it reminds me of + memory.',cn:'每当我听到某段音乐，它就让我想起……',example:'Whenever I hear that song, it reminds me of my first year at university.'},{pattern:'Music can change the atmosphere of + place or event + by + gerund.',cn:'音乐可以通过……改变某个场所或活动的氛围。',example:'Music can change the atmosphere of a film scene by creating tension before anything happens.'},{pattern:'Even without understanding the lyrics, listeners may + verb.',cn:'即使听不懂歌词，听众也可能……',example:'Even without understanding the lyrics, listeners may respond to the rhythm and tone.'}],
